jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';
const text = document.createElement('div');
text.className = 'hacker-text';
const finalWord = 'CYBERSPACE';
text.innerText = finalWord;
c.appendChild(text);

const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&*';
let interval = null;

text.addEventListener('pointerenter', () => {
  let iteration = 0;
  clearInterval(interval);
  interval = setInterval(() => {
    text.innerText = text.innerText.split('').map((letter, index) => {
      if(index < iteration) return finalWord[index];
      return letters[Math.floor(Math.random() * letters.length)];
    }).join('');
    if(iteration >= finalWord.length) clearInterval(interval);
    iteration += 1 / 3;
  }, 30);
});
